83	static void init_balls(void)
84	{
85	  int i, j;
86	  lv_obj_t *parent = lv_screen_active();
87	  int sw = lv_display_get_horizontal_resolution(NULL);
88	  int sh = lv_display_get_vertical_resolution(NULL);
89	
90	  for (i = 0; i < NUM_BALLS; i++)
91	    {
92	      g_anim.balls[i].radius = 15.0f + randf(0, 20);
93	      g_anim.balls[i].x = randf(g_anim.balls[i].radius,
94	                                 sw - g_anim.balls[i].radius);
95	      g_anim.balls[i].y = randf(g_anim.balls[i].radius,
96	                                 sh - g_anim.balls[i].radius);
97	      g_anim.balls[i].vx = randf(1.5f, 4.0f) * (rand() % 2 ? 1 : -1);
98	      g_anim.balls[i].vy = randf(1.5f, 4.0f) * (rand() % 2 ? 1 : -1);
99	      g_anim.balls[i].color = lv_color_hex(g_palette[i]);
100	
101	      /* Create trail circles */
102	
103	      for (j = 0; j < TRAIL_LENGTH; j++)
104	        {
105	          lv_obj_t *t = lv_obj_create(parent);
106	          lv_obj_remove_style_all(t);
107	          lv_obj_set_size(t, (int)(g_anim.balls[i].radius * 2 * (1.0f -
108	                          j * 0.12f)),
109	                          (int)(g_anim.balls[i].radius * 2 * (1.0f -
110	                          j * 0.12f)));
111	          lv_obj_set_style_radius(t, LV_RADIUS_CIRCLE, 0);
112	          lv_obj_set_style_bg_color(t, g_anim.balls[i].color, 0);
113	          lv_obj_set_style_bg_opa(t, LV_OPA_100 - j * 15, 0);
114	          lv_obj_set_pos(t, (int)g_anim.balls[i].x,
115	                         (int)g_anim.balls[i].y);
116	          g_anim.balls[i].trail[j] = t;
117	          g_anim.balls[i].trail_x[j] = g_anim.balls[i].x;
118	          g_anim.balls[i].trail_y[j] = g_anim.balls[i].y;
119	        }
120	
121	      /* Create main ball */
122	
123	      g_anim.balls[i].ball = lv_obj_create(parent);
124	      lv_obj_remove_style_all(g_anim.balls[i].ball);
125	      lv_obj_set_size(g_anim.balls[i].ball,
126	                      (int)(g_anim.balls[i].radius * 2),
127	                      (int)(g_anim.balls[i].radius * 2));
128	      lv_obj_set_style_radius(g_anim.balls[i].ball, LV_RADIUS_CIRCLE, 0);
129	      lv_obj_set_style_bg_color(g_anim.balls[i].ball,
130	                                g_anim.balls[i].color, 0);
131	      lv_obj_set_style_bg_opa(g_anim.balls[i].ball, LV_OPA_100, 0);
132	      lv_obj_set_pos(g_anim.balls[i].ball,
133	                     (int)g_anim.balls[i].x,
134	                     (int)g_anim.balls[i].y);
135	    }
136	}
