138	static void update_balls(void)
139	{
140	  int i, j;
141	  int sw = lv_display_get_horizontal_resolution(NULL);
142	  int sh = lv_display_get_vertical_resolution(NULL);
143	
144	  for (i = 0; i < NUM_BALLS; i++)
145	    {
146	      /* Shift trail positions */
147	
148	      for (j = TRAIL_LENGTH - 1; j > 0; j--)
149	        {
150	          g_anim.balls[i].trail_x[j] = g_anim.balls[i].trail_x[j - 1];
151	          g_anim.balls[i].trail_y[j] = g_anim.balls[i].trail_y[j - 1];
152	        }
153	
154	      g_anim.balls[i].trail_x[0] = g_anim.balls[i].x;
155	      g_anim.balls[i].trail_y[0] = g_anim.balls[i].y;
156	
157	      /* Update position */
158	
159	      g_anim.balls[i].x += g_anim.balls[i].vx;
160	      g_anim.balls[i].y += g_anim.balls[i].vy;
161	
162	      /* Bounce off walls */
163	
164	      if (g_anim.balls[i].x < g_anim.balls[i].radius)
165	        {
166	          g_anim.balls[i].x = g_anim.balls[i].radius;
167	          g_anim.balls[i].vx = -g_anim.balls[i].vx * 0.95f;
168	        }
169	
170	      if (g_anim.balls[i].x > sw - g_anim.balls[i].radius)
171	        {
172	          g_anim.balls[i].x = sw - g_anim.balls[i].radius;
173	          g_anim.balls[i].vx = -g_anim.balls[i].vx * 0.95f;
174	        }
175	
176	      if (g_anim.balls[i].y < g_anim.balls[i].radius)
177	        {
178	          g_anim.balls[i].y = g_anim.balls[i].radius;
179	          g_anim.balls[i].vy = -g_anim.balls[i].vy * 0.95f;
180	        }
181	
182	      if (g_anim.balls[i].y > sh - g_anim.balls[i].radius)
183	        {
184	          g_anim.balls[i].y = sh - g_anim.balls[i].radius;
185	          g_anim.balls[i].vy = -g_anim.balls[i].vy * 0.95f;
186	        }
187	
188	      /* Add slight gravity and random perturbation */
189	
190	      g_anim.balls[i].vy += 0.02f;
191	      g_anim.balls[i].vx += randf(-0.05f, 0.05f);
192	      g_anim.balls[i].vy += randf(-0.05f, 0.05f);
193	
194	      /* Speed limit */
195	
196	      float speed = sqrtf(g_anim.balls[i].vx * g_anim.balls[i].vx +
197	                          g_anim.balls[i].vy * g_anim.balls[i].vy);
198	      if (speed > 6.0f)
199	        {
200	          g_anim.balls[i].vx *= 6.0f / speed;
201	          g_anim.balls[i].vy *= 6.0f / speed;
202	        }
203	
204	      /* Update trail objects */
205	
206	      for (j = 0; j < TRAIL_LENGTH; j++)
207	        {
208	          float r = g_anim.balls[i].radius * (1.0f - j * 0.12f);
209	          lv_obj_set_pos(g_anim.balls[i].trail[j],
210	                         (int)(g_anim.balls[i].trail_x[j] - r),
211	                         (int)(g_anim.balls[i].trail_y[j] - r));
212	        }
213	
214	      /* Update main ball */
215	
216	      lv_obj_set_pos(g_anim.balls[i].ball,
217	                     (int)(g_anim.balls[i].x - g_anim.balls[i].radius),
218	                     (int)(g_anim.balls[i].y - g_anim.balls[i].radius));
219	    }
220	}
