245	static void create_wave_canvas(void)
246	{
247	  int sw = lv_display_get_horizontal_resolution(NULL);
248	  int w = sw - 40;
249	  int h = 120;
250	
251	  g_anim.wave_canvas = lv_canvas_create(lv_screen_active());
252	
253	  /* Allocate buffer for canvas - ARGB8888 = 4 bytes per pixel */
254	
255	  uint32_t buf_size = w * h * 4;
256	  void *buf = malloc(buf_size);
257	  if (!buf)
258	    {
259	      LV_LOG_ERROR("Failed to allocate canvas buffer");
260	      g_anim.wave_canvas = NULL;
261	      return;
262	    }
263	
264	  lv_canvas_set_buffer(g_anim.wave_canvas, buf, w, h,
265	                       LV_COLOR_FORMAT_ARGB8888);
266	  lv_obj_align(g_anim.wave_canvas, LV_ALIGN_BOTTOM_MID, 0, -50);
267	}
