348	static void update_fps(void)
349	{
350	  g_anim.frame_count++;
351	  uint32_t now = lv_tick_get();
352	  uint32_t elapsed = now - g_anim.last_tick;
353	
354	  if (elapsed >= 1000)
355	    {
356	      uint32_t fps = g_anim.frame_count * 1000 / elapsed;
357	      char buf[64];
358	      snprintf(buf, sizeof(buf), "FPS: %lu  Frames: %lu",
359	               (unsigned long)fps, (unsigned long)g_anim.frame_count);
360	      lv_label_set_text(g_anim.fps_label, buf);
361	      g_anim.frame_count = 0;
362	      g_anim.last_tick = now;
363	    }
364	}
