377	int main(int argc, FAR char *argv[])
378	{
379	  lv_nuttx_dsc_t info;
380	  lv_nuttx_result_t result;
381	
382	  if (lv_is_initialized())
383	    {
384	      LV_LOG_ERROR("LVGL already initialized! aborting.");
385	      return -1;
386	    }
387	
388	#ifdef CONFIG_BOARDCTL
389	#  ifndef CONFIG_NSH_ARCHINIT
390	  boardctl(BOARDIOC_INIT, 0);
391	#  endif
392	#endif
393	
394	  lv_init();
395	  lv_nuttx_dsc_init(&info);
396	
397	#ifdef CONFIG_LV_USE_NUTTX_LCD
398	  info.fb_path = "/dev/lcd0";
399	#endif
400	
401	#ifdef CONFIG_INPUT_TOUCHSCREEN
402	  info.input_path = "/dev/input0";
403	#endif
404	
405	  lv_nuttx_init(&info, &result);
406	
407	  if (result.disp == NULL)
408	    {
409	      LV_LOG_ERROR("Display initialization failure!");
410	      return 1;
411	    }
412	
413	  /* Set dark background */
414	
415	  lv_obj_set_style_bg_color(lv_screen_active(),
416	                             lv_color_hex(0x1A1A2E), 0);
417	  lv_obj_set_style_bg_opa(lv_screen_active(), LV_OPA_100, 0);
418	
419	  /* Seed random number generator */
420	
421	  srand(lv_tick_get());
422	
423	  /* Initialize animation elements */
424	
425	  memset(&g_anim, 0, sizeof(g_anim));
426	  g_anim.last_tick = lv_tick_get();
427	
428	  create_title();
429	  create_fps_label();
430	  init_balls();
431	  create_wave_canvas();
432	
433	  /* Create animation timer - 16ms interval (~60 FPS target) */
434	
435	  lv_timer_create(anim_timer_cb, 16, NULL);
436	
437	  /* Main loop */
438	
439	  while (1)
440	    {
441	      uint32_t idle = lv_timer_handler();
442	      idle = idle ? idle : 1;
443	      usleep(idle * 1000);
444	    }
445	
446	  return 0;
447	}
